SELECT wr_reason_sk, i_category, total_loss, return_cnt, loss_category, DENSE_RANK() OVER (ORDER BY total_loss DESC) AS loss_rank, LAG(total_loss) OVER (ORDER BY total_loss DESC) AS prev_loss, total_loss - LAG(total_loss) OVER (ORDER BY total_loss DESC) AS loss_diff FROM ( SELECT wr.wr_reason_sk, i.i_category, SUM(wr.wr_net_loss) AS total_loss, COUNT(*) AS return_cnt, CASE WHEN SUM(wr.wr_net_loss) > 20000 THEN 'HIGH' WHEN SUM(wr.wr_net_loss) > 10000 THEN 'MEDIUM' ELSE 'LOW' END AS loss_category FROM web_returns wr JOIN item i ON wr.wr_item_sk = i.i_item_sk JOIN customer_address ca ON wr.wr_returning_addr_sk = ca.ca_address_sk GROUP BY wr.wr_reason_sk, i.i_category ) agg ORDER BY loss_rank
